query Browse($first: Int! = 20, $after: String, $locale: String! = "en") {
  titles(first: $first, after: $after) {
    edges {
      cursor
      node {
        id
        localized(locale: $locale) {
          locale
          title
          synopsis
          __typename
        }
        runtimeSeconds
        releaseYear
        languages
        genres
        accessibility
        editorialLabels
        credits {
          name
          role
          __typename
        }
        artwork {
          url
          altText
          attribution {
            creator
            licenseUrl
            __typename
          }
          __typename
        }
        attribution {
          workTitle
          creator
          copyrightHolder
          sourceUrl
          licenseName
          licenseVersion
          licenseUrl
          attributionText
          modificationNotice
          __typename
        }
        __typename
      }
      __typename
    }
    pageInfo {
      endCursor
      hasNextPage
      __typename
    }
    __typename
  }
}

query ContinueWatching($profileId: ID!, $first: Int! = 20, $after: String) {
  continueWatching(profileId: $profileId, first: $first, after: $after) {
    code
    correlationId
    connection {
      edges {
        cursor
        node {
          id
          titleId
          positionMs
          durationMs
          status
          title {
            id
            localized {
              title
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      pageInfo {
        endCursor
        hasNextPage
        __typename
      }
      __typename
    }
    __typename
  }
}

